<?php define('IN_CRONLITE',true);require_once(dirname(__FILE__).'/../includes/common.php');header('Content-Type:application/json');require_login();$data=json_decode(file_get_contents('php://input'),1);$id=intval($data['id']??0);$status=intval($data['status']??0);if($id<=0||!in_array($status,[2,3]))exit(json_encode(['code'=>1,'msg'=>'参数错误']));$user_id=get_current_user_id();$DB->query("UPDATE ad_creatives SET status=$status,audit_user_id=$user_id,audit_time=NOW() WHERE id=$id");$DB->query("INSERT INTO ad_audit_logs(audit_type,audit_object_id,auditor_id,action,created_at)VALUES('creative',$id,$user_id,$status==2?'pass':'reject',NOW())");exit(json_encode(['code'=>0,'msg'=>'审核成功']));
